/// wl_data_offer: offer to transfer data
public enum WlDataOffer: Interface {
    public static let name = "wl_data_offer"
    public static let version: UInt32 = 4

    public enum Request {
        /// accept one of the offered mime types
        case accept(serial: UInt32, mimeType: String?)
        /// request that the data is transferred
        case receive(mimeType: String, fd: Int32)
        /// destroy data offer
        case destroy
        /// the offer will no longer be used
        case finish
        /// set the available/preferred drag-and-drop actions
        case setActions(dndActions: UInt32, preferredAction: UInt32)
    }

    public static func decode(opcode: UInt16, from message: inout MessageReader, version: UInt32) throws(ProtocolError) -> Request {
        switch opcode {
        case 0:
            let serial = try message.uint()
            let mimeType = try message.optionalString()
            return .accept(serial: serial, mimeType: mimeType)
        case 1:
            let mimeType = try message.string()
            let fd = try message.fd()
            return .receive(mimeType: mimeType, fd: fd)
        case 2:
            return .destroy
        case 3:
            guard version >= 3 else { throw message.invalidOpcode(opcode) }
            return .finish
        case 4:
            guard version >= 3 else { throw message.invalidOpcode(opcode) }
            let dndActions = try message.uint()
            let preferredAction = try message.uint()
            return .setActions(dndActions: dndActions, preferredAction: preferredAction)
        default:
            throw message.invalidOpcode(opcode)
        }
    }

    public static func isDestructor(opcode: UInt16) -> Bool {
        [2].contains(opcode)
    }

    public enum ErrorCode: UInt32, Sendable {
        /// finish request was called untimely
        case invalidFinish = 0
        /// action mask contains invalid values
        case invalidActionMask = 1
        /// action argument has an invalid value
        case invalidAction = 2
        /// offer doesn't accept this request
        case invalidOffer = 3
    }
}

