/// wl_shell_surface: desktop-style metadata interface
public enum WlShellSurface: Interface {
    public static let name = "wl_shell_surface"
    public static let version: UInt32 = 1

    public enum Request {
        /// respond to a ping event
        case pong(serial: UInt32)
        /// start an interactive move
        case move(seat: Resource<WlSeat>, serial: UInt32)
        /// start an interactive resize
        case resize(seat: Resource<WlSeat>, serial: UInt32, edges: UInt32)
        /// make the surface a toplevel surface
        case setToplevel
        /// make the surface a transient surface
        case setTransient(parent: Resource<WlSurface>, x: Int32, y: Int32, flags: UInt32)
        /// make the surface a fullscreen surface
        case setFullscreen(method: UInt32, framerate: UInt32, output: Resource<WlOutput>?)
        /// make the surface a popup surface
        case setPopup(seat: Resource<WlSeat>, serial: UInt32, parent: Resource<WlSurface>, x: Int32, y: Int32, flags: UInt32)
        /// make the surface a maximized surface
        case setMaximized(output: Resource<WlOutput>?)
        /// set surface title
        case setTitle(title: String)
        /// set surface class
        case setClass(class: String)
    }

    public static func decode(opcode: UInt16, from message: inout MessageReader, version: UInt32) throws(ProtocolError) -> Request {
        switch opcode {
        case 0:
            let serial = try message.uint()
            return .pong(serial: serial)
        case 1:
            let seat = try message.object(WlSeat.self)
            let serial = try message.uint()
            return .move(seat: seat, serial: serial)
        case 2:
            let seat = try message.object(WlSeat.self)
            let serial = try message.uint()
            let edges = try message.uint()
            return .resize(seat: seat, serial: serial, edges: edges)
        case 3:
            return .setToplevel
        case 4:
            let parent = try message.object(WlSurface.self)
            let x = try message.int()
            let y = try message.int()
            let flags = try message.uint()
            return .setTransient(parent: parent, x: x, y: y, flags: flags)
        case 5:
            let method = try message.uint()
            let framerate = try message.uint()
            let output = try message.optionalObject(WlOutput.self)
            return .setFullscreen(method: method, framerate: framerate, output: output)
        case 6:
            let seat = try message.object(WlSeat.self)
            let serial = try message.uint()
            let parent = try message.object(WlSurface.self)
            let x = try message.int()
            let y = try message.int()
            let flags = try message.uint()
            return .setPopup(seat: seat, serial: serial, parent: parent, x: x, y: y, flags: flags)
        case 7:
            let output = try message.optionalObject(WlOutput.self)
            return .setMaximized(output: output)
        case 8:
            let title = try message.string()
            return .setTitle(title: title)
        case 9:
            let `class` = try message.string()
            return .setClass(class: `class`)
        default:
            throw message.invalidOpcode(opcode)
        }
    }

    public static func isDestructor(opcode: UInt16) -> Bool {
        false
    }

    /// edge values for resizing
    public struct Resize: OptionSet, Sendable {
        public let rawValue: UInt32
        public init(rawValue: UInt32) { self.rawValue = rawValue }
        /// top edge
        public static let top = Resize(rawValue: 1)
        /// bottom edge
        public static let bottom = Resize(rawValue: 2)
        /// left edge
        public static let left = Resize(rawValue: 4)
        /// top and left edges
        public static let topLeft = Resize(rawValue: 5)
        /// bottom and left edges
        public static let bottomLeft = Resize(rawValue: 6)
        /// right edge
        public static let right = Resize(rawValue: 8)
        /// top and right edges
        public static let topRight = Resize(rawValue: 9)
        /// bottom and right edges
        public static let bottomRight = Resize(rawValue: 10)
    }

    /// details of transient behaviour
    public struct Transient: OptionSet, Sendable {
        public let rawValue: UInt32
        public init(rawValue: UInt32) { self.rawValue = rawValue }
        /// do not set keyboard focus
        public static let inactive = Transient(rawValue: 0x1)
    }

    /// different method to set the surface fullscreen
    public enum FullscreenMethod: UInt32, Sendable {
        /// no preference, apply default policy
        case `default` = 0
        /// scale, preserve the surface's aspect ratio and center on output
        case scale = 1
        /// switch output mode to the smallest mode that can fit the surface, add black borders to compensate size mismatch
        case driver = 2
        /// no upscaling, center on output and add black borders to compensate size mismatch
        case fill = 3
    }
}

