/// wl_surface: an onscreen surface
public enum WlSurface: Interface {
    public static let name = "wl_surface"
    public static let version: UInt32 = 7

    public enum Request {
        /// delete surface
        case destroy
        /// set the surface contents
        case attach(buffer: Resource<WlBuffer>?, x: Int32, y: Int32)
        /// mark part of the surface damaged
        case damage(x: Int32, y: Int32, width: Int32, height: Int32)
        /// request a frame throttling hint
        case frame(callback: NewID<WlCallback>)
        /// set opaque region
        case setOpaqueRegion(region: Resource<WlRegion>?)
        /// set input region
        case setInputRegion(region: Resource<WlRegion>?)
        /// commit pending surface state
        case commit
        /// sets the buffer transformation
        case setBufferTransform(transform: Int32)
        /// sets the buffer scaling factor
        case setBufferScale(scale: Int32)
        /// mark part of the surface damaged using buffer coordinates
        case damageBuffer(x: Int32, y: Int32, width: Int32, height: Int32)
        /// set the surface contents offset
        case offset(x: Int32, y: Int32)
        /// get a release callback
        case getRelease(callback: NewID<WlCallback>)
    }

    public static func decode(opcode: UInt16, from message: inout MessageReader, version: UInt32) throws(ProtocolError) -> Request {
        switch opcode {
        case 0:
            return .destroy
        case 1:
            let buffer = try message.optionalObject(WlBuffer.self)
            let x = try message.int()
            let y = try message.int()
            return .attach(buffer: buffer, x: x, y: y)
        case 2:
            let x = try message.int()
            let y = try message.int()
            let width = try message.int()
            let height = try message.int()
            return .damage(x: x, y: y, width: width, height: height)
        case 3:
            let callback = try message.newID(WlCallback.self, version: version)
            return .frame(callback: callback)
        case 4:
            let region = try message.optionalObject(WlRegion.self)
            return .setOpaqueRegion(region: region)
        case 5:
            let region = try message.optionalObject(WlRegion.self)
            return .setInputRegion(region: region)
        case 6:
            return .commit
        case 7:
            guard version >= 2 else { throw message.invalidOpcode(opcode) }
            let transform = try message.int()
            return .setBufferTransform(transform: transform)
        case 8:
            guard version >= 3 else { throw message.invalidOpcode(opcode) }
            let scale = try message.int()
            return .setBufferScale(scale: scale)
        case 9:
            guard version >= 4 else { throw message.invalidOpcode(opcode) }
            let x = try message.int()
            let y = try message.int()
            let width = try message.int()
            let height = try message.int()
            return .damageBuffer(x: x, y: y, width: width, height: height)
        case 10:
            guard version >= 5 else { throw message.invalidOpcode(opcode) }
            let x = try message.int()
            let y = try message.int()
            return .offset(x: x, y: y)
        case 11:
            guard version >= 7 else { throw message.invalidOpcode(opcode) }
            let callback = try message.newID(WlCallback.self, version: version)
            return .getRelease(callback: callback)
        default:
            throw message.invalidOpcode(opcode)
        }
    }

    public static func isDestructor(opcode: UInt16) -> Bool {
        [0].contains(opcode)
    }

    /// wl_surface error values
    public enum ErrorCode: UInt32, Sendable {
        /// buffer scale value is invalid
        case invalidScale = 0
        /// buffer transform value is invalid
        case invalidTransform = 1
        /// buffer size is invalid
        case invalidSize = 2
        /// buffer offset is invalid
        case invalidOffset = 3
        /// surface was destroyed before its role object
        case defunctRoleObject = 4
        /// no buffer was attached
        case noBuffer = 5
    }
}

