    public static func decode(opcode: UInt16, from message: inout MessageReader, version: UInt32) throws(ProtocolError) -> Request {
        switch opcode {
        case 0:
            let serial = try message.uint()
            let surface = try message.optionalObject(WlSurface.self)
            let hotspotX = try message.int()
            let hotspotY = try message.int()
            return .setCursor(serial: serial, surface: surface, hotspotX: hotspotX, hotspotY: hotspotY)
        case 1:
            guard version >= 3 else { throw message.invalidOpcode(opcode) }
            return .release
        default:
            throw message.invalidOpcode(opcode)
        }
    }

    public static func isDestructor(opcode: UInt16) -> Bool {
        [1].contains(opcode)
    }

    public enum ErrorCode: UInt32, Sendable {
        /// given wl_surface has another role
        case role = 0
    }

    /// physical button state
    public enum ButtonState: UInt32, Sendable {
        /// the button is not pressed
        case released = 0
        /// the button is pressed
        case pressed = 1
    }

    /// axis types
    public enum Axis: UInt32, Sendable {
        /// vertical axis
        case verticalScroll = 0
        /// horizontal axis
        case horizontalScroll = 1
    }

    /// axis source types
    public enum AxisSource: UInt32, Sendable {
        /// a physical wheel rotation
        case wheel = 0
        /// finger on a touch surface
        case finger = 1
        /// continuous coordinate space
        case continuous = 2
        /// a physical wheel tilt
        case wheelTilt = 3
    }

    /// axis relative direction
    public enum AxisRelativeDirection: UInt32, Sendable {
        /// physical motion matches axis direction
        case identical = 0
        /// physical motion is the inverse of the axis direction
        case inverted = 1
    }
}

