        /// no geometry
        case none = 1
        /// horizontal RGB
        case horizontalRgb = 2
        /// horizontal BGR
        case horizontalBgr = 3
        /// vertical RGB
        case verticalRgb = 4
        /// vertical BGR
        case verticalBgr = 5
    }

